import{_ as e,o,c as t,a5 as r}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 8 话 渐变：参数化的绘图语言","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.08-gradients.md","filePath":"comics/css/EP.08-gradients.md","lastUpdated":1793421609000}'),i={name:"comics/css/EP.08-gradients.md"};function d(n,a,c,s,l,h){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="漫画-·-第-8-话-渐变-参数化的绘图语言" tabindex="-1">漫画 · 第 8 话 渐变：参数化的绘图语言 <a class="header-anchor" href="#漫画-·-第-8-话-渐变-参数化的绘图语言" aria-label="Permalink to &quot;漫画 · 第 8 话 渐变：参数化的绘图语言&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/08-gradients">docs/css/08-gradients.md</a> ｜ 原画：<a href="./EP.08-gradients.svg">EP.08-gradients.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。想给渐变按钮加 hover 过渡，颜色却瞬间&quot;跳变&quot;，transition 集体失灵。</li><li><strong>标签君</strong>：HTML5 结构师，画出 linear / radial / conic 三种渐变的等色线示意，并演示纯 CSS 饼图。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>渐变不是&quot;背景图&quot;，而是浏览器实时计算的 <code>&lt;image&gt;</code> 类型——凡能放图片的地方都能放渐变。像素酱先弄懂三种渐变的插值方向，再用 conic 接力写法画环形进度，最后学会渐变动画的两条正路：动 background-position，或用 @property 注册角度变量。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>background-image</code> 是离散值，<code>transition</code> 对它完全无效——hover 换渐变只会瞬间跳变。要&quot;颜色流动&quot;，正确姿势有两条：把渐变画成 200% 宽、动画 <code>background-position</code>（可插值的长度值）；或用 <code>@property</code> 把角度/百分比注册成自定义属性后写进 keyframes。都不可行时，叠两层渐变用 opacity 交叉淡化。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三种渐变三种等色线：<code>linear-gradient</code> 沿渐变轴线插值（垂直于轴的每条线同色）；<code>radial-gradient</code> 从中心沿半径插值（等色线是椭圆/圆）；<code>conic-gradient</code> 绕中心旋转插值（等色线是射线）。渐变没有固有尺寸，作为背景默认铺满定位区，所以<strong>天然自适应</strong>；hard-stop（两个色标同位置）让插值区间为零，条纹、饼图、格纹的全部秘密都在这里。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>conic 饼图的&quot;接力写法&quot;：<code>conic-gradient(#22d3ee 0 calc(var(--p) * 3.6deg), #1e293b 0)</code>——第二个色标起点写 0 但被钳制到前一段终点，于是第一色画 0→p%、第二色自动铺满剩余角度；JS 只需 <code>setProperty(&#39;--p&#39;, 72)</code> 一个数字。流动按钮则是&quot;超宽渐变 + position 动画&quot;：观感是渐变在流动，实际只是背景在平移。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>渐变是 <code>&lt;image&gt;</code> 类型——background / mask / border-image 都能放，无固有尺寸天然自适应。</li><li>background-image 不可过渡：流动用 200% 超宽渐变动 position，或 @property 注册角度。</li><li>repeating 周期 = 最后一个色标位置；渐变文字要 background-clip: text 三件套。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：<code>conic-gradient(#22d3ee 0 calc(var(--p) * 3.6deg), #1e293b 0)</code> 里，第二个色标的起点写 0 为什么也能画对饼图？</p><p><strong>答</strong>：色标位置会被&quot;钳制&quot;到前一个色标的终点——起点 0 实际等于前色终点，于是青色画 0→p%、深色从 p% 自动&quot;接力&quot;铺满到 100%。这就是接力写法：JS 只提供一个 0~100 的数字，CSS 负责换算成角度。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>linear / radial 实验台：角度、色标、hard-stop 条纹：<a href="./../../examples/css/08-gradients/index-01-linear-radial.html">examples/css/08-gradients/</a></li><li>conic 色轮/饼图 + repeating 条纹、格纹、网格纸：<a href="./../../examples/css/08-gradients/index-02-conic-repeating.html">index-02-conic-repeating.html</a></li><li>渐变文字、渐变边框、渐变 + 动画组合：<a href="./../../examples/css/08-gradients/index-03-gradient-text-border.html">index-03-gradient-text-border.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 9 话《Transform》——不触发重排的变形魔法：translate、rotate、scale 与 3D。</p>',22)])])}const g=e(i,[["render",d]]);export{u as __pageData,g as default};
